package auth

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/ecdh"
	"crypto/hkdf"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"strings"
	"testing"
)

// Fixed cross-language vector. The same values are asserted by the API Lambda
// (cli-token-encryption.test.ts) and the login page (CliLogin.test.ts), and were
// generated by an independent implementation, so passing here proves this
// decryptor is wire-compatible with the server and browser encryptors.
const (
	vectorCLIPrivHex = "1111111111111111111111111111111111111111111111111111111111111111"
	vectorCLIKey     = "BAIX5hfwtkQ5KCePlpmeaaI6TywVK99tbN9m5bgCgtTtGUp968uXcS0t2jyoWqh2Wlb0X8dYWZZS8ol8ZTBuV5Q"
	vectorState      = "state-0123456789"
	vectorPlaintext  = "eyJhbGciOiJSUzI1NiJ9.eyJzdWIiOiJ1c2VyIn0.c2ln"
	vectorEnc        = "BNZak5d8qj0bCBhS_1ennkZfFmBXcwS66tUF3TpIWJzzUBheiVNy32Ih6joTdVfkc_3bZ1XwW9UHw8Uz_OnJEoUzMzMzMzMzMzMzMzP7Zrgfw9drpSgaz4CTKzMEp2--1JJ_yTftPaJkuc2obNgu-pyBr_0x0PtlxzcbDhHaagDJd1UA2dPKovfP"
)

func vectorKey(t *testing.T) *loginKey {
	t.Helper()
	raw, err := hex.DecodeString(vectorCLIPrivHex)
	if err != nil {
		t.Fatal(err)
	}
	priv, err := ecdh.P256().NewPrivateKey(raw)
	if err != nil {
		t.Fatal(err)
	}
	return &loginKey{priv: priv}
}

// encryptForTest implements the sender side of the scheme (what the server and the
// login page do), so Go tests can produce payloads for a given public key.
func encryptForTest(t *testing.T, cliKey, state, plaintext string) string {
	t.Helper()
	pubRaw, err := base64.RawURLEncoding.DecodeString(cliKey)
	if err != nil {
		t.Fatal(err)
	}
	pub, err := ecdh.P256().NewPublicKey(pubRaw)
	if err != nil {
		t.Fatal(err)
	}
	eph, err := ecdh.P256().GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	secret, err := eph.ECDH(pub)
	if err != nil {
		t.Fatal(err)
	}
	key, err := hkdf.Key(sha256.New, secret, []byte(state), hkdfInfo, 32)
	if err != nil {
		t.Fatal(err)
	}
	block, _ := aes.NewCipher(key)
	gcm, _ := cipher.NewGCM(block)
	iv := make([]byte, gcmIVLen)
	if _, err := rand.Read(iv); err != nil {
		t.Fatal(err)
	}
	sealed := gcm.Seal(nil, iv, []byte(plaintext), []byte(state))
	out := bytes.Join([][]byte{eph.PublicKey().Bytes(), iv, sealed}, nil)
	return base64.RawURLEncoding.EncodeToString(out)
}

func TestDecryptFixedVectorFromServerAndBrowser(t *testing.T) {
	k := vectorKey(t)
	if got := k.publicParam(); got != vectorCLIKey {
		t.Fatalf("publicParam = %q, want the vector key", got)
	}
	got, err := k.decrypt(vectorState, vectorEnc)
	if err != nil {
		t.Fatalf("decrypt vector: %v", err)
	}
	if got != vectorPlaintext {
		t.Errorf("plaintext = %q, want %q", got, vectorPlaintext)
	}
}

func TestLoginKeyRoundTripAndPublicParamShape(t *testing.T) {
	k, err := newLoginKey()
	if err != nil {
		t.Fatal(err)
	}
	pub := k.publicParam()
	raw, err := base64.RawURLEncoding.DecodeString(pub)
	if err != nil || len(raw) != 65 || raw[0] != 0x04 {
		t.Fatalf("publicParam must be a 65-byte uncompressed point, got len=%d err=%v", len(raw), err)
	}
	if len(pub) != 87 {
		t.Errorf("encoded key length = %d, want 87 (server/UI pattern)", len(pub))
	}
	enc := encryptForTest(t, pub, "state-0123456789abcdef", "a.b.c")
	if strings.Contains(enc, "a.b.c") {
		t.Error("ciphertext contains the plaintext")
	}
	got, err := k.decrypt("state-0123456789abcdef", enc)
	if err != nil || got != "a.b.c" {
		t.Fatalf("round trip = %q, %v", got, err)
	}
}

func TestLoginKeysAreUniquePerLogin(t *testing.T) {
	a, _ := newLoginKey()
	b, _ := newLoginKey()
	if a.publicParam() == b.publicParam() {
		t.Error("two logins must not share a key pair")
	}
}

func TestDecryptRejectsWrongKeyStateAndTampering(t *testing.T) {
	k, _ := newLoginKey()
	attacker, _ := newLoginKey() // a process squatting the port, with its own key
	const state = "state-0123456789abcdef"
	enc := encryptForTest(t, k.publicParam(), state, "secret-token")

	if _, err := attacker.decrypt(state, enc); err == nil {
		t.Error("a different private key must not decrypt the payload")
	}
	if _, err := k.decrypt("state-OTHER-0123456789", enc); err == nil {
		t.Error("wrong state must fail authentication (AAD/salt binding)")
	}

	raw, _ := base64.RawURLEncoding.DecodeString(enc)
	raw[len(raw)-1] ^= 0x01 // flip a bit in the tag
	if _, err := k.decrypt(state, base64.RawURLEncoding.EncodeToString(raw)); err == nil {
		t.Error("tampered tag must be rejected")
	}
	raw, _ = base64.RawURLEncoding.DecodeString(enc)
	raw[80] ^= 0x01 // flip a bit in the ciphertext
	if _, err := k.decrypt(state, base64.RawURLEncoding.EncodeToString(raw)); err == nil {
		t.Error("tampered ciphertext must be rejected")
	}
}

func TestDecryptRejectsMalformedInput(t *testing.T) {
	k, _ := newLoginKey()
	const state = "state-0123456789abcdef"
	cases := map[string]string{
		"empty":        "",
		"not base64":   "!!!not-base64!!!",
		"too short":    base64.RawURLEncoding.EncodeToString(make([]byte, 40)),
		"off-curve":    base64.RawURLEncoding.EncodeToString(append([]byte{0x04}, make([]byte, 120)...)),
		"oversize":     strings.Repeat("A", maxEncodedEncB+1),
		"bad prefix":   base64.RawURLEncoding.EncodeToString(make([]byte, 120)),
		"plain id_tok": "eyJhbGciOiJSUzI1NiJ9.eyJzdWIiOiJ1c2VyIn0.c2ln",
	}
	for name, enc := range cases {
		t.Run(name, func(t *testing.T) {
			if _, err := k.decrypt(state, enc); err == nil {
				t.Error("expected an error")
			}
		})
	}
	if _, err := k.decrypt("short", "AAAA"); err == nil {
		t.Error("a malformed state must be rejected")
	}
}
